import { initializeApp } from "firebase/app";
import { getAuth, GoogleAuthProvider, signInWithPopup, onAuthStateChanged, signOut } from "firebase/auth";

let authInstance;
let googleProvider;

export const initFirebase = async () => {
  if (authInstance) return authInstance;

  try {
    const response = await fetch("/api/config/firebase");
    const config = await response.json();
    if (config.error) throw new Error(config.error);

    const app = initializeApp(config);
    authInstance = getAuth(app);
    googleProvider = new GoogleAuthProvider();
    return authInstance;
  } catch (error) {
    console.error("Firebase init failed:", error);
    // Fallback to project ID from URL or common naming
    const app = initializeApp({ projectId: "jarvis-a6e18" });
    authInstance = getAuth(app);
    googleProvider = new GoogleAuthProvider();
    return authInstance;
  }
};

// Getter to be used after initialization
export const getAuthInstance = () => {
  if (!authInstance) throw new Error("Firebase not initialized. Call initFirebase() first.");
  return authInstance;
};

export const loginWithGoogle = async () => {
  const auth = await initFirebase();
  try {
    const result = await signInWithPopup(auth, googleProvider);
    const token = await result.user.getIdToken();
    localStorage.setItem('firebase_token', token);
    localStorage.setItem('user', JSON.stringify({
      uid: result.user.uid,
      email: result.user.email,
      displayName: result.user.displayName,
      photoURL: result.user.photoURL
    }));
    return result.user;
  } catch (error) {
    console.error("Login failed:", error);
    throw error;
  }
};

export const logout = async () => {
  const auth = await initFirebase();
  await signOut(auth);
  localStorage.removeItem('firebase_token');
  localStorage.removeItem('user');
};
